441	bool bes_codec_dev_vpu_process(void *src_data, void *dst_data,
442	                               uint32_t src_size, uint32_t dst_capacity,
443	                               uint32_t *dst_size)
444	{
445	  static uint32_t traced;
446	  static uint32_t last_w;
447	  static uint32_t last_h;
448	  static uint32_t last_fmt;
449	  uint32_t luma_size;
450	  uint32_t chroma_size;
451	  uint32_t stride;
452	  FAR uint8_t *luma_va;
453	  bool trace;
454	  enum DecRet ret;
455	
456	  *dst_size = 0;
457	
458	  if (src_data == NULL || dst_data == NULL)
459	    {
460	      verr("null buffer src=%p dst=%p\n", src_data, dst_data);
461	      return false;
462	    }
463	
464	  if (((uintptr_t)src_data & 0xf) != 0 || ((uintptr_t)dst_data & 0xf) != 0)
465	    {
466	      verr("buffer not 128-bit aligned src=%p dst=%p\n", src_data, dst_data);
467	      return false;
468	    }
469	
470	  memset(&_jpeg_in, 0, sizeof(JpegDecInput));
471	  memset(&_image_info, 0, sizeof(JpegDecImageInfo));
472	
473	  _jpeg_in.stream_buffer.virtual_address = (u32 *)src_data;
474	  _jpeg_in.stream_buffer.bus_address     = (addr_t)src_data;
475	  _jpeg_in.stream_buffer.logical_size    = src_size;
476	  _jpeg_in.stream_buffer.size            = ALIGN64(src_size);
477	  _jpeg_in.stream_buffer.mem_type        = DWL_MEM_TYPE_DMA_HOST_TO_DEVICE |
478	                                           DWL_MEM_TYPE_CPU;
479	  SET_MEM_USAGE(_jpeg_in.stream_buffer.mem_type, DWL_MEM_USAGE_IN_STRM, 0);
480	
481	  _jpeg_in.stream_length  = src_size;
482	  _jpeg_in.buffer_size    = 0;
483	  _jpeg_in.stream         = (u8 *)src_data;
484	  _jpeg_in.thumbnail_done = 0;
485	
486	  cache_flush(src_data, ALIGN64(src_size));
487	
488	  ret = JpegDecGetImageInfo(_dec_inst, &_jpeg_in, &_image_info);
489	  if (ret)
490	    {
491	      verr("JpegDecGetImageInfo failed ret %d\n", ret);
492	      return false;
493	    }
494	
495	  trace = traced < VPU_TRACE_FRAMES ||
496	          _image_info.output_width  != last_w ||
497	          _image_info.output_height != last_h ||
498	          _image_info.output_format != last_fmt;
499	
500	  last_w   = _image_info.output_width;
501	  last_h   = _image_info.output_height;
502	  last_fmt = _image_info.output_format;
503	
504	  if (traced < VPU_TRACE_FRAMES)
505	    {
506	      traced++;
507	    }
508	
509	  if (trace)
510	    {
511	      vinfo("image %ux%u visible %ux%u fmt %u align %d\n",
512	            _image_info.output_width, _image_info.output_height,
513	            _image_info.display_width, _image_info.display_height,
514	            _image_info.output_format, _image_info.align);
515	    }
516	
517	  if (_image_info.output_width == 0 || _image_info.output_height == 0)
518	    {
519	      verr("decoder reported a zero sized image\n");
520	      return false;
521	    }
522	
523	  luma_size   = _image_info.output_width * _image_info.output_height;
524	  chroma_size = luma_size / 2;
525	
526	  if (luma_size + chroma_size > dst_capacity)
527	    {
528	      verr("decoded %ux%u needs %u bytes, capture buffer is %u\n",
529	           _image_info.output_width, _image_info.output_height,
530	           luma_size + chroma_size, dst_capacity);
531	      return false;
532	    }
533	
534	  if (!bes_codec_vpu_buffer_known(dst_data))
535	    {
536	      if (_reg_count >= BES_VPU_MAX_REG_BUFFERS)
537	        {
538	          verr("cannot register %p, all %d slots used; the consumer is "
539	               "cycling more buffers than the decoder can hold\n",
540	               dst_data, BES_VPU_MAX_REG_BUFFERS);
541	          return false;
542	        }
543	
544	      memset(&_mem, 0, sizeof(struct DWLLinearMem));
545	      _mem.virtual_address = (u32 *)dst_data;
546	      _mem.bus_address     = (addr_t)dst_data;
547	      _mem.logical_size    = luma_size + chroma_size;
548	      _mem.size            = luma_size + chroma_size;
549	      _mem.mem_type        = DWL_MEM_TYPE_DPB;
550	      SET_MEM_USAGE(_mem.mem_type, DWL_MEM_USAGE_OUT_PP, 0);
551	
552	      ret = JpegDecAddBuffer(_dec_inst, &_mem);
553	      if (ret)
554	        {
555	          verr("JpegDecAddBuffer(%p, %u) failed ret %d\n",
556	               dst_data, luma_size + chroma_size, ret);
557	          return false;
558	        }
559	
560	      _reg_buffers[_reg_count++] = dst_data;
561	      vinfo("registered buffer %p, %d of %d slots used\n",
562	            dst_data, _reg_count, BES_VPU_MAX_REG_BUFFERS);
563	    }
564	
565	  bes_codec_vpu_set_pp(&_dec_cfg, _image_info.output_width,
566	                       _image_info.output_height);
567	
568	  ret = JpegDecSetInfo(_dec_inst, &_dec_cfg);
569	  if (ret)
570	    {
571	      verr("JpegDecSetInfo failed ret %d\n", ret);
572	      return false;
573	    }
574	
575	  memset(&_hbuf, 0, sizeof(struct DecBufferInfo));
576	  if (JpegDecGetBufferInfo(_dec_inst, &_hbuf) == DEC_OK && trace)
577	    {
578	      vinfo("wants %llu bytes x %u, ystride %u cstride %u\n",
579	            (unsigned long long)_hbuf.next_buf_size, _hbuf.buf_num,
580	            _hbuf.ystride[0], _hbuf.cstride[0]);
581	    }
582	
583	  cache_flush(dst_data, ALIGN64(luma_size + chroma_size));
584	
585	  memset(&_jpeg_out, 0, sizeof(JpegDecOutput));
586	  ret = JpegDecDecode(_dec_inst, &_jpeg_in, &_jpeg_out);
587	
588	  if (trace)
589	    {
590	      vinfo("decode ret %d %ux%u stride %u/%u out_y %p\n", ret,
591	            _jpeg_out.pictures[0].output_width,
592	            _jpeg_out.pictures[0].output_height,
593	            _jpeg_out.pictures[0].pic_stride,
594	            _jpeg_out.pictures[0].pic_stride_ch,
595	            (void *)_jpeg_out.pictures[0].output_picture_y.bus_address);
596	    }
597	
598	  if (ret != DEC_PIC_RDY)
599	    {
600	      verr("JpegDecDecode failed ret %d\n", ret);
601	      return false;
602	    }
603	
604	  ret = JpegDecNextPicture(_dec_inst, &_jpeg_out, &_image_info);
605	
606	  stride  = _jpeg_out.pictures[0].pic_stride;
607	  luma_va = (uint8_t *)_jpeg_out.pictures[0].output_picture_y.virtual_address;
608	
609	  if (trace)
610	    {
611	      vinfo("next ret %d %ux%u stride %u/%u out_y %p\n", ret,
612	            _jpeg_out.pictures[0].output_width,
613	            _jpeg_out.pictures[0].output_height,
614	            stride, _jpeg_out.pictures[0].pic_stride_ch, luma_va);
615	    }
616	
617	  if (ret != DEC_PIC_RDY && ret != DEC_OK)
618	    {
619	      verr("JpegDecNextPicture failed ret %d\n", ret);
620	      return false;
621	    }
622	
623	  if (luma_va == NULL)
624	    {
625	      verr("no output picture address\n");
626	      return false;
627	    }
628	
629	  if (_jpeg_out.pictures[0].output_picture_y.bus_address != (addr_t)dst_data)
630	    {
631	      verr("PP wrote to %p but the capture buffer is %p; the decoder is not "
632	           "honouring the per frame AddBuffer\n",
633	           (void *)_jpeg_out.pictures[0].output_picture_y.bus_address,
634	           dst_data);
635	      return false;
636	    }
637	
638	  if (stride != 0 && stride != _image_info.output_width)
639	    {
640	      verr("PP stride %u != padded width %u, capture bytesperline is wrong\n",
641	           stride, _image_info.output_width);
642	    }
643	
644	  if (_jpeg_out.pictures[0].output_height != 0)
645	    {
646	      uint32_t out_stride = stride ? stride :
647	                            _jpeg_out.pictures[0].output_width;
648	
649	      luma_size   = out_stride * _jpeg_out.pictures[0].output_height;
650	      chroma_size = luma_size / 2;
651	    }
652	
653	  if (luma_size + chroma_size > dst_capacity)
654	    {
655	      verr("decoded %u bytes, capture buffer is %u\n",
656	           luma_size + chroma_size, dst_capacity);
657	      return false;
658	    }
659	
660	  cache_invalid(dst_data, ALIGN64(luma_size + chroma_size));
661	
662	  JpegDecPictureConsumed(_dec_inst, &_jpeg_out);
663	
664	  *dst_size = luma_size + chroma_size;
665	
666	  if (trace)
667	    {
668	      vinfo("dst_size = %u\n", *dst_size);
669	    }
670	  return true;
671	}
