675	 *
676	 * Description:
677	 *   Core processing routine — called from the work queue.  Fetches one
678	 *   buffer from the OUTPUT queue and one from the CAPTURE queue, then
679	 *   drives the hardware codec to produce a result.

680	 *
681	 *   For a decoder:
682	 *     - OUTPUT  = compressed bitstream (H.264 / H.265 / ...)
683	 *     - CAPTURE = decoded raw frame (YUV420 / NV12 / ...)
684	 *
685	 *   For an encoder:
686	 *     - OUTPUT  = raw frame (YUV420 / NV12 / ...)
687	 *     - CAPTURE = compressed bitstream
688	 *
689	 *   TODO: replace the skeleton body with actual BES hardware codec API
690	 *   calls (e.g. bes_vdec_decode_frame / bes_venc_encode_frame).
691	 *
692	 ****************************************************************************/
693	
694	static int bes_codec_process(FAR struct bes_codec_priv_s *priv,
695	                             FAR struct v4l2_buffer *dst_buf,
696	                             FAR struct v4l2_buffer *src_buf)
697	{
698	  struct v4l2_event event;
699	  uint8_t *src_data = NULL;
700	  uint32_t src_size = 0;
701	  int64_t src_pts   = 0;
702	  int64_t dst_pts   = 0;
703	  int ret;
704	
705	  if (src_buf != NULL){
706	    src_data = (uint8_t *)src_buf->m.vaddr;
707	    src_size = src_buf->bytesused;
708	    src_pts  = src_buf->timestamp.tv_sec * 1000000 + src_buf->timestamp.tv_usec;
709	  }else{
710	    priv->flushing = false;
711	    dst_buf->flags |= V4L2_BUF_FLAG_LAST;
712	    dst_buf->bytesused = 0;
713	    memset(&event, 0, sizeof(event));
714	    event.type = V4L2_EVENT_EOS;
715	    vinfo("event eos\n");
716	    codec_queue_event(priv->cookie, &event);
717	    codec_capture_put_buf(priv->cookie, dst_buf);
718	    return 0;
719	  }
720	  uint32_t isize = src_size;
721	  uint32_t osize = 0;
722	  void* idata = src_data;
723	  void* odata = dst_buf->m.vaddr;
724	  uint32_t ocap = (uint32_t)bes_codec_capture_g_bufsize(priv);
725	
726	  if (g_process_traced < VPU_TRACE_FRAMES)
727	    {
728	      g_process_traced++;
729	      vinfo("isize=%u idata=%p odata=%p ocap=%u\n", isize, idata, odata,
730	            ocap);
731	    }
732	  bool dec_ret = bes_codec_dev_vpu_process(idata, odata, isize, ocap,
733	                                           &osize);
734	  if(dec_ret && osize){
735	    ret = 1;
736	  }else{
737	    ret = 0;
738	  }
739	
740	  // ret = 1;  /* placeholder: assume one output frame produced */
741	
742	  /* Return the consumed source buffer to the framework */
743	
744	  if (ret >= 0 && src_buf != NULL)
745	    {
746	      codec_output_put_buf(priv->cookie, src_buf);
747	    }
748	
749	  if (ret < 1)
750	    {
751	      dst_buf->bytesused = 0;
752	      dst_buf->flags |= V4L2_BUF_FLAG_ERROR;
753	      codec_capture_put_buf(priv->cookie, dst_buf);
754	      return ret;
755	    }
756	
757	  dst_buf->flags &= ~V4L2_BUF_FLAG_ERROR;
758	  dst_buf->bytesused = osize;
759	  /* TODO: dequeue the result from hardware and fill dst_buf.
760	   *
761	   * Decoder path:
762	   *   ret = bes_vdec_dequeue(priv->hw_handle, dst_buf->m.vaddr,
763	   *                          &dst_pts, &dst_buf->bytesused);
764	   *
765	   * Encoder path:
766	   *   ret = bes_venc_dequeue(priv->hw_handle, dst_buf->m.vaddr,
767	   *                          &dst_buf->bytesused, &dst_pts,
768	   *                          &dst_buf->flags);
769	   */
770	
771	  /* Handle flush completion */
772	
773	  dst_buf->timestamp.tv_usec = dst_pts % 1000000;
774	  dst_buf->timestamp.tv_sec  = dst_pts / 1000000;
775	
776	  codec_capture_put_buf(priv->cookie, dst_buf);
777	  return ret;
778	}
