780	/****************************************************************************
781	 * Name: bes_codec_work
782	 *
783	 * Description:
784	 *   Work queue callback.  Tries to dequeue one OUTPUT buffer and one
785	 *   CAPTURE buffer, processes them through the hardware codec, and
786	 *   re-arms itself if more data is available.
787	 *
788	 *   This follows the pattern recommended in the V4L2 M2M development
789	 *   guide: dequeue all processed buffers before queuing new ones.
790	 *
791	 ****************************************************************************/
792	
793	static void bes_codec_work(void *arg)
794	{
795	  FAR struct bes_codec_priv_s *priv = arg;
796	  FAR struct v4l2_buffer *src_buf;
797	  FAR struct v4l2_buffer *dst_buf;
798	  int ret;
799	
800	  DEBUGASSERT(priv != NULL);
801	
802	  if (!priv->output_on && !priv->flushing){
803	    return;
804	  }
805	
806	  /* Try to get one compressed/raw input buffer from the OUTPUT queue */
807	
808	  src_buf = codec_output_get_buf(priv->cookie);
809	  if (src_buf == NULL && !priv->flushing)
810	    {
811	      return;
812	    }
813	
814	  /* Try to get one free output buffer from the CAPTURE queue */
815	
816	  dst_buf = codec_capture_get_buf(priv->cookie);
817	  if (dst_buf == NULL)
818	    {
819	      return;
820	    }
821	
822	  ret = bes_codec_process(priv, dst_buf, src_buf);
823	
824	  /* If the hardware produced output, schedule another pass to drain
825	   * any remaining buffers.
826	   */
827	
828	  if (ret > 0)
829	    {
830	      work_queue(HPWORK, &priv->work, bes_codec_work, priv, 0);
831	    }
832	}
